const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Number.isFinite(n)?Number(n.toPrecision(5)).toLocaleString():'—';
export const ML_ALGORITHMS={extra_trees:'Extra Trees',random_forest:'Random Forest',hist_gradient_boosting:'HistGradientBoosting',gradient_boosting:'Gradient Boosting',ridge:'Ridge 岭回归',elastic_net:'Elastic Net',svr:'SVR 支持向量回归',mlp:'MLP 神经网络'};
export function trainingControls(settings,engine){return `<div class="prediction-engine-status" role="status">${engine?.ready?`成熟库引擎已就绪 · scikit-learn ${esc(engine.versions['scikit-learn'])} · Python ${esc(engine.python)}`:esc(engine?.error||'正在检查机器学习运行环境…')}</div><fieldset><legend>候选算法 · 通过内层验证选择</legend><div class="prediction-property-choices">${Object.entries(ML_ALGORITHMS).map(([id,label])=>`<label class="prediction-check"><input name="algorithm" type="checkbox" value="${id}" ${settings.algorithms.includes(id)?'checked':''}>${label}</label>`).join('')}</div></fieldset><div class="prediction-grid"><label>参数搜索<select name="search"><option value="standard" ${settings.search==='standard'?'selected':''}>标准搜索</option><option value="thorough" ${settings.search==='thorough'?'selected':''}>全面搜索 · 更多参数组合</option></select></label><label>集成树数量<input name="trees" type="number" min="32" max="2048" value="${settings.trees}"></label><label>计算线程<input name="threads" type="number" min="1" max="32" value="${settings.threads}"></label><label>随机种子<input name="seed" type="number" min="0" max="2147483647" value="${settings.seed}"></label></div>`;}
function chart(points,residual=false){
 if(!points.length)return'';
 const sample=points.filter((_,i)=>i%Math.max(1,Math.ceil(points.length/1000))===0);
 const xs=sample.map(p=>residual?p.predicted:p.actual),ys=sample.map(p=>residual?p.actual-p.predicted:p.predicted);
 const extent=values=>{let lo=Math.min(...values),hi=Math.max(...values);if(lo===hi){lo--;hi++;}const pad=(hi-lo)*.05;return[lo-pad,hi+pad];};
 const [xl,xh]=extent(residual?xs:[...xs,...ys]),[yl,yh]=residual?extent([...ys,0]):[xl,xh];
 const x=v=>50+(v-xl)/(xh-xl)*330,y=v=>210-(v-yl)/(yh-yl)*180;
 return`<figure class="prediction-chart"><figcaption>${residual?'折外残差 · 横轴预测值，纵轴实测 − 预测':'折外预测 · 横轴实测值，纵轴预测值'}</figcaption><svg viewBox="0 0 410 245" role="img" aria-label="${residual?'残差图':'实测与预测散点图'}"><path d="M50 20V210H390" fill="none" stroke="currentColor" opacity=".4"/><line x1="50" y1="${residual?y(0):210}" x2="380" y2="${residual?y(0):30}" stroke="currentColor" stroke-dasharray="5 4" opacity=".5"/>${sample.map((p,i)=>`<circle cx="${x(xs[i])}" cy="${y(ys[i])}" r="3" fill="var(--accent,#5278bf)" opacity=".65"><title>实测 ${num(p.actual)} · 预测 ${num(p.predicted)} · 第 ${p.fold||'—'} 折</title></circle>`).join('')}<text x="50" y="230" fill="currentColor" font-size="11">${num(xl)}</text><text x="335" y="230" fill="currentColor" font-size="11">${num(xh)}</text><text x="2" y="35" fill="currentColor" font-size="11">${num(yh)}</text><text x="2" y="210" fill="currentColor" font-size="11">${num(yl)}</text></svg></figure>`;
}
export function modelReport(m){if(!m)return'';const t=m.training,metrics=m.metrics;return`<section class="prediction-card prediction-model-report"><div class="prediction-card-title"><h3>${esc(m.property.name)} · 训练报告</h3><button class="text-button" data-prediction-action="close-report">收起</button></div><p>${esc(m.estimator||'旧版自实现 Extra Trees')} · ${m.usable?'通过均值基线对照':'未优于均值基线，未启用'}${t?' · 外层 5 折评估 / 内层 3 折选型调参':''}</p><div class="prediction-metrics">${[['MAE',metrics.mae],['RMSE',metrics.rmse],['R²',metrics.r2],['基线 MAE',metrics.baselineMAE],['P90 绝对误差',metrics.errorP90],['训练秒数',t?.seconds]].map(([label,v])=>`<div><small>${label}</small><strong>${num(v)}</strong></div>`).join('')}</div><div class="prediction-two-col">${chart(m.validationPoints)}${chart(m.validationPoints,true)}</div>${t?`<p class="prediction-help">以下排名来自全部数据上的内层调参，不能替代上方的外层误差。最终模型使用全部有效数据重新拟合；算法选择在各外层折内部独立进行。</p><div class="prediction-table-wrap"><table><thead><tr><th>候选算法与参数</th><th>内层 MAE ± 折间标准差</th><th>训练 MAE</th></tr></thead><tbody>${t.leaderboard.map(r=>`<tr><td>${esc(JSON.stringify(r.params))}</td><td>${num(r.mae)} ± ${num(r.std)}</td><td>${num(r.trainMAE)}</td></tr>`).join('')}</tbody></table></div><details><summary>折外置换重要性 · 正值表示置换后 MAE 增大</summary>${m.featureImportance.map(f=>`<p>${esc(f.name)}：${num(f.importance)} ± ${num(f.std)}</p>`).join('')}<p class="prediction-help">按各折平均，单位与目标一致。相关输入会分摊重要性；该结果不表示因果关系。</p></details><details><summary>复现信息与训练提示</summary><p>环境：${esc(JSON.stringify(m.environment))}</p><p>数据指纹：${esc(t.dataSHA256)}</p><p>最终参数：${esc(JSON.stringify(t.bestParams))}</p><p>设置：${esc(JSON.stringify(t.options))}</p>${t.warnings.map(w=>`<p class="prediction-warning">${esc(w)}</p>`).join('')||'<p>无库级训练警告。</p>'}</details>`:''}<div class="prediction-actions"><button class="outline-button" data-export-validation="${esc(m.id)}">导出全部折外结果 CSV</button><button class="outline-button" data-export-report="${esc(m.id)}">导出完整训练报告 JSON</button></div></section>`;}
